// Kind is what kind of item something is, and what that means for a loan.
type Kind interface {
	LoanDays() int
	DailyFee() int
	Label(title string) string
	Shelf() string
	Renewable() bool
}

// Book is a book.
type Book struct{}

func (Book) LoanDays() int             { return 21 }
func (Book) DailyFee() int             { return 10 }
func (Book) Label(title string) string { return title }
func (Book) Shelf() string             { return "stacks" }
func (Book) Renewable() bool           { return true }

// DVD is a film on a disc.
type DVD struct{}

func (DVD) LoanDays() int             { return 7 }
func (DVD) DailyFee() int             { return 50 }
func (DVD) Label(title string) string { return "DVD: " + title }
func (DVD) Shelf() string             { return "media" }
func (DVD) Renewable() bool           { return true }

// Atlas is a reference atlas.
type Atlas struct{}

func (Atlas) LoanDays() int             { return 3 }
func (Atlas) DailyFee() int             { return 100 }
func (Atlas) Label(title string) string { return strings.ToUpper(title) + " (reference)" }
func (Atlas) Shelf() string             { return "reference" }
func (Atlas) Renewable() bool           { return false }

// kindOf is the kind named name, or nil.
func kindOf(name string) Kind {
	switch name {
	case "book":
		return Book{}
	case "dvd":
		return DVD{}
	case "atlas":
		return Atlas{}
	}
	return nil
}

if it.Kind == nil {
	return 0
}
return it.Kind.LoanDays()

if it.Kind == nil {
	return 0
}
return it.Kind.DailyFee()

if it.Kind == nil {
	return it.Title
}
return it.Kind.Label(it.Title)

if it.Kind == nil {
	return "returns"
}
return it.Kind.Shelf()

var items []Item
var lines []int
var names []string
for i, line := range strings.Split(text, "\n") {
	line = strings.TrimSpace(line)
	if line == "" || strings.HasPrefix(line, "#") {
		continue
	}
	f := strings.Split(line, "|")
	if len(f) != 4 {
		return fmt.Errorf("line %d: want 4 fields, got %d", i+1, len(f))
	}
	n, err := strconv.Atoi(strings.TrimSpace(f[3]))
	if err != nil {
		return fmt.Errorf("line %d: copies: %v", i+1, err)
	}
	name := strings.TrimSpace(f[2])
	items = append(items, Item{ID: strings.TrimSpace(f[0]), Title: strings.TrimSpace(f[1]), Kind: kindOf(name), Copies: n})
	lines = append(lines, i+1)
	names = append(names, name)
}
seen := map[string]bool{}
for k, it := range items {
	if it.ID == "" {
		return fmt.Errorf("line %d: no id", lines[k])
	}
	if LoanDays(it) == 0 {
		return fmt.Errorf("line %d: unknown kind %q", lines[k], names[k])
	}
	if it.Copies <= 0 {
		return fmt.Errorf("line %d: no copies", lines[k])
	}
	if _, there := c.Items[it.ID]; there || seen[it.ID] {
		return fmt.Errorf("line %d: %s is already there", lines[k], it.ID)
	}
	seen[it.ID] = true
}
if c.Items == nil {
	c.Items = map[string]Item{}
}
for _, it := range items {
	c.Items[it.ID] = it
}
return nil
